import assert from "node:assert/strict";
import test from "node:test";
import {
	buildNotice,
	FORKS_URL,
	forkCommand,
	isSafeSessionId,
	LEARN_PROMPT,
	learnPrompt,
	parseLearnInput,
	REGISTER_TIMEOUT_MS,
	registerFork,
} from "./learn-fork.ts";

const SOURCE = "0f0e5a8e-1d4c-4f1c-9d1a-2b3c4d5e6f70";
const SESSION = "5b1c9c2f-7e44-4a6b-8c3d-1e2f3a4b5c6d";

test("recognises both spellings of the learn command", () => {
	assert.deepEqual(parseLearnInput("/skill:learn"), { args: "", here: false });
	assert.deepEqual(parseLearnInput("/learn"), { args: "", here: false });
	assert.deepEqual(parseLearnInput("/skill:learn foo"), { args: "foo", here: false });
	assert.deepEqual(parseLearnInput("/learn foo bar"), { args: "foo bar", here: false });
	assert.deepEqual(parseLearnInput("  /learn foo  "), { args: "foo", here: false });
	assert.deepEqual(parseLearnInput("/skill:learn   multiple   spaces"), {
		args: "multiple   spaces",
		here: false,
	});
});

test("treats a first argument of here as in-session learn", () => {
	assert.deepEqual(parseLearnInput("/learn here"), { args: "", here: true });
	assert.deepEqual(parseLearnInput("/skill:learn here"), { args: "", here: true });
	assert.deepEqual(parseLearnInput("/learn here x"), { args: "x", here: true });
	assert.deepEqual(parseLearnInput("/skill:learn here foo bar"), { args: "foo bar", here: true });
});

test("ignores text that is not a learn command", () => {
	assert.equal(parseLearnInput(""), undefined);
	assert.equal(parseLearnInput("learn foo"), undefined);
	assert.equal(parseLearnInput("/learning"), undefined);
	assert.equal(parseLearnInput("/learnx foo"), undefined);
	assert.equal(parseLearnInput("/skill:learn-here"), undefined);
	assert.equal(parseLearnInput("please /learn foo"), undefined);
	assert.equal(parseLearnInput("/skill:other foo"), undefined);
	// `here` only counts as the first argument.
	assert.deepEqual(parseLearnInput("/learn foo here"), { args: "foo here", here: false });
});

test("accepts only session ids Pi can pin", () => {
	assert.equal(isSafeSessionId(SESSION), true);
	assert.equal(isSafeSessionId("abc_1.2-3"), true);
	assert.equal(isSafeSessionId(""), false);
	assert.equal(isSafeSessionId("-abc"), false);
	assert.equal(isSafeSessionId("a/b"), false);
	assert.equal(isSafeSessionId("has space"), false);
	assert.equal(isSafeSessionId("x".repeat(97)), false);
});

test("builds the fork prompt", () => {
	assert.equal(learnPrompt(""), LEARN_PROMPT);
	assert.equal(learnPrompt("  "), LEARN_PROMPT);
	assert.equal(learnPrompt("foo"), "/skill:learn here foo");
	assert.equal(learnPrompt(" foo bar "), "/skill:learn here foo bar");
});

test("builds the hand-run command", () => {
	assert.equal(forkCommand(SOURCE, SESSION, ""), `pi --fork ${SOURCE} --session-id ${SESSION} "/skill:learn here"`);
	assert.equal(
		forkCommand(SOURCE, SESSION, "foo"),
		`pi --fork ${SOURCE} --session-id ${SESSION} "/skill:learn here foo"`,
	);
	assert.equal(
		forkCommand(SOURCE, SESSION, 'say "hi"'),
		`pi --fork ${SOURCE} --session-id ${SESSION} "/skill:learn here say \\"hi\\""`,
	);
});

test("notice names the fork and points at the dashboard when registered", () => {
	assert.equal(
		buildNotice({ sessionId: SESSION, sourceSession: SOURCE, args: "foo", registered: true }),
		`learn → fork ${SESSION} · pi --session ${SESSION} · dashboard floating`,
	);
	assert.equal(
		buildNotice({ sessionId: SESSION, sourceSession: SOURCE, args: "foo", registered: true, projectName: "scripts", pane: 3 }),
		`learn → fork ${SESSION} · pi --session ${SESSION} · dashboard scripts #3`,
	);
	assert.equal(
		buildNotice({
			sessionId: SESSION,
			sourceSession: SOURCE,
			args: "foo",
			registered: true,
			resume: "pi --session 5b1c",
		}),
		`learn → fork ${SESSION} · pi --session 5b1c · dashboard floating`,
	);
});

test("a refused registration says why", () => {
	assert.match(
		buildNotice({ sessionId: SESSION, sourceSession: SOURCE, args: "", registered: false, refused: "Not here." }),
		/ · dashboard refused: Not here\.$/,
	);
});

test("notice carries the command when the dashboard did not register the fork", () => {
	assert.equal(
		buildNotice({ sessionId: SESSION, sourceSession: SOURCE, args: "foo", registered: false }),
		`learn → fork ${SESSION} · pi --session ${SESSION} · run: pi --fork ${SOURCE} --session-id ${SESSION} "/skill:learn here foo"`,
	);
	assert.equal(
		buildNotice({ sessionId: SESSION, sourceSession: SOURCE, args: "", registered: false }),
		`learn → fork ${SESSION} · pi --session ${SESSION} · run: pi --fork ${SOURCE} --session-id ${SESSION} "/skill:learn here"`,
	);
});

function jsonResponse(status: number, body: unknown): Response {
	return new Response(JSON.stringify(body), {
		status,
		headers: { "content-type": "application/json" },
	});
}

test("registers the fork with the dashboard and keeps its resume line", async () => {
	const calls: { url: string; init: RequestInit }[] = [];
	const fetchImpl = (async (url: string, init: RequestInit) => {
		calls.push({ url, init });
		return jsonResponse(201, { id: `fork-${SESSION}`, resume: `pi --session ${SESSION}` });
	}) as unknown as typeof fetch;

	const result = await registerFork(
		{ cwd: "/home/easydev/dev/dashboard", sourceSession: SOURCE, sessionId: SESSION, args: " foo " },
		{ fetchImpl },
	);

	assert.deepEqual(result, { registered: true, status: 201, resume: `pi --session ${SESSION}` });
	assert.equal(calls.length, 1);
	assert.equal(calls[0]?.url, FORKS_URL);
	assert.equal(calls[0]?.init.method, "POST");
	assert.deepEqual(JSON.parse(String(calls[0]?.init.body)), {
		harness: "pi",
		cwd: "/home/easydev/dev/dashboard",
		sourceSession: SOURCE,
		sessionId: SESSION,
		args: "foo",
	});
	assert.equal(REGISTER_TIMEOUT_MS, 1500);
});

test("omits empty args from the request body", async () => {
	const bodies: unknown[] = [];
	const fetchImpl = (async (_url: string, init: RequestInit) => {
		bodies.push(JSON.parse(String(init.body)));
		return jsonResponse(201, { id: `fork-${SESSION}`, resume: `pi --session ${SESSION}` });
	}) as unknown as typeof fetch;

	await registerFork({ cwd: "/tmp", sourceSession: SOURCE, sessionId: SESSION, args: "   " }, { fetchImpl });
	assert.deepEqual(bodies, [{ harness: "pi", cwd: "/tmp", sourceSession: SOURCE, sessionId: SESSION }]);
});

test("a rejected registration resolves unregistered with the server's error", async () => {
	const fetchImpl = (async () => jsonResponse(400, { error: "cwd must be under $HOME" })) as unknown as typeof fetch;
	assert.deepEqual(
		await registerFork({ cwd: "/etc", sourceSession: SOURCE, sessionId: SESSION, args: "" }, { fetchImpl }),
		{ registered: false, status: 400, error: "cwd must be under $HOME" },
	);
});

test("a dashboard that is down or slow resolves unregistered", async () => {
	const down = (async () => {
		throw new Error("connect ECONNREFUSED 127.0.0.1:45111");
	}) as unknown as typeof fetch;
	assert.deepEqual(
		await registerFork({ cwd: "/tmp", sourceSession: SOURCE, sessionId: SESSION, args: "" }, { fetchImpl: down }),
		{ registered: false, error: "connect ECONNREFUSED 127.0.0.1:45111" },
	);

	const hangs = (async (_url: string, init: RequestInit) => {
		await new Promise((_resolve, reject) => {
			init.signal?.addEventListener("abort", () => reject(new Error("timed out")));
		});
		return jsonResponse(201, {});
	}) as unknown as typeof fetch;
	const started = Date.now();
	const result = await registerFork(
		{ cwd: "/tmp", sourceSession: SOURCE, sessionId: SESSION, args: "" },
		{ fetchImpl: hangs, timeoutMs: 30 },
	);
	assert.equal(result.registered, false);
	assert.ok(Date.now() - started < 1000);
});

test("a 201 without a JSON body still counts as registered", async () => {
	const fetchImpl = (async () => new Response("", { status: 201 })) as unknown as typeof fetch;
	assert.deepEqual(
		await registerFork({ cwd: "/tmp", sourceSession: SOURCE, sessionId: SESSION, args: "" }, { fetchImpl }),
		{ registered: true, status: 201, resume: undefined },
	);
});

