/**
 * `/learn` fork helpers: parse the invocation, register the fork with the dashboard, and build
 * the one-line notice. Pure — the extension supplies the session id and the process does the
 * POST, so every piece here is testable without a live Pi session.
 *
 * Contract (`docs/plan/261106-learn-fork-terminal.md` §3): the dashboard's `POST /api/forks`
 * takes `{harness, cwd, sourceSession, sessionId, args?}` and answers `201 {id, resume}`; it
 * assembles argv itself, so no command text ever leaves here.
 */

export const FORKS_URL = "http://127.0.0.1:45111/api/forks";

/** Dashboard registration is best-effort: a miss only changes the notice. */
export const REGISTER_TIMEOUT_MS = 1500;

/** The fork always opens with `here`, so its own hook passes the prompt through. */
export const LEARN_PROMPT = "/skill:learn here";

const LEARN_PATTERN = /^\/(?:skill:learn|learn)(?:\s+([\s\S]*))?$/;

/** Pi session ids: Pi accepts letters, numbers, `.`, `_`, `-` (cli.md `--session-id`). */
const SESSION_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,95}$/;

export interface LearnInput {
	/** Text after `/skill:learn` (or `/learn`), with a leading `here` removed. */
	args: string;
	/** First argument is `here`: learn runs in this session instead of a fork. */
	here: boolean;
}

/**
 * Recognise `/skill:learn [args]` and `/learn [args]` in the raw input event text.
 * `undefined` for anything else (Pi then expands it as usual).
 */
export function parseLearnInput(text: string): LearnInput | undefined {
	const match = LEARN_PATTERN.exec(text.trim());
	if (!match) return undefined;
	const rest = (match[1] ?? "").trim();
	if (rest === "") return { args: "", here: false };
	if (rest === "here") return { args: "", here: true };
	const hereArgs = /^here\s+([\s\S]*)$/.exec(rest);
	if (hereArgs) return { args: hereArgs[1].trim(), here: true };
	return { args: rest, here: false };
}

export function isSafeSessionId(id: string): boolean {
	return SESSION_ID_PATTERN.test(id);
}

/** The prompt a fork session starts with. */
export function learnPrompt(args: string): string {
	const trimmed = args.trim();
	return trimmed ? `${LEARN_PROMPT} ${trimmed}` : LEARN_PROMPT;
}

/** Quoted for display only: the dashboard assembles argv, nothing here is executed. */
function quote(text: string): string {
	return JSON.stringify(text);
}

/** The command that reproduces the fork by hand. */
export function forkCommand(sourceSession: string, sessionId: string, args: string): string {
	return `pi --fork ${sourceSession} --session-id ${sessionId} ${quote(learnPrompt(args))}`;
}

export interface NoticeInput {
	sessionId: string;
	sourceSession: string;
	args: string;
	/** The dashboard accepted `POST /api/forks`. */
	registered: boolean;
	/** `resume` echoed by the dashboard, e.g. `pi --session <id>`. */
	resume?: string;
}

/**
 * One line for the TUI: the fork id always, plus `· dashboard Forks` when the dashboard owns
 * the process, or the full command to run when it does not.
 */
export function buildNotice(input: NoticeInput): string {
	const resume = input.resume?.trim() || `pi --session ${input.sessionId}`;
	const head = `learn → fork ${input.sessionId} · ${resume}`;
	if (input.registered) return `${head} · dashboard Forks`;
	return `${head} · run: ${forkCommand(input.sourceSession, input.sessionId, input.args)}`;
}

export interface ForkRequest {
	cwd: string;
	/** Current session id: the fork continues its history. */
	sourceSession: string;
	/** Id chosen here and pinned with `--session-id`, so the notice names the real session. */
	sessionId: string;
	args: string;
}

export interface ForkRegistration {
	registered: boolean;
	status?: number;
	/** `resume` from the 201 body, when present. */
	resume?: string;
	error?: string;
}

export interface RegisterOptions {
	url?: string;
	timeoutMs?: number;
	fetchImpl?: typeof fetch;
}

/** `POST /api/forks`. Every failure resolves `{registered:false}` — the caller still forks by hand. */
export async function registerFork(request: ForkRequest, options: RegisterOptions = {}): Promise<ForkRegistration> {
	const url = options.url ?? FORKS_URL;
	const timeoutMs = options.timeoutMs ?? REGISTER_TIMEOUT_MS;
	const fetchImpl = options.fetchImpl ?? fetch;
	const args = request.args.trim();
	const body = {
		harness: "pi",
		cwd: request.cwd,
		sourceSession: request.sourceSession,
		sessionId: request.sessionId,
		...(args ? { args } : {}),
	};
	try {
		const res = await fetchImpl(url, {
			method: "POST",
			headers: { "content-type": "application/json" },
			body: JSON.stringify(body),
			signal: AbortSignal.timeout(timeoutMs),
		});
		if (!res.ok) {
			return { registered: false, status: res.status, error: await errorFrom(res) };
		}
		let resume: string | undefined;
		try {
			const payload = (await res.json()) as { resume?: unknown } | undefined;
			if (typeof payload?.resume === "string") resume = payload.resume;
		} catch {
			// A 201 without a JSON body is still a registration.
		}
		return { registered: true, status: res.status, resume };
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		return { registered: false, error: message };
	}
}

async function errorFrom(res: Response): Promise<string | undefined> {
	try {
		const payload = (await res.json()) as { error?: unknown } | undefined;
		if (typeof payload?.error === "string") return payload.error;
	} catch {
		// Fall through to the status-only result.
	}
	return undefined;
}

