export function buildNotice(input: NoticeInput): string {
	const resume = input.resume?.trim() || `pi --session ${input.sessionId}`;
	const head = `learn → fork ${input.sessionId} · ${resume}`;
	if (input.registered) {
		const projectName = input.projectName?.trim();
		const target = projectName ? `${projectName}${input.pane !== undefined ? ` #${input.pane}` : ""}` : "floating";
		return `${head} · dashboard ${target}`;
	}
	const refused = input.refused?.trim();
	if (refused) return `${head} · dashboard refused: ${refused}`;
	return `${head} · run: ${forkCommand(input.sourceSession, input.sessionId, input.args)}`;
}

